SELECT  

    AND f.work_order_id=#{workOrderId}
    AND f.finished_lot_id=#{lotId}
    AND LOCATE(#{lotNo},CONVERT(f.lot_no USING utf8mb4)) > 0
    AND (LOCATE(#{keyword},CONVERT(i.item_code USING utf8mb4)) > 0 OR LOCATE(#{keyword},i.item_name) > 0)
 ORDER BY q.inspection_id DESC

SELECT receipt_id,scope_key,operation_code,request_key,payload_fingerprint,
    initial_outcome_snapshot AS snapshot,processed_at,created_by FROM request_receipt
WHERE scope_key=#{scopeKey} AND operation_code='QUALITY_INSPECTION' AND request_key=#{requestKey}
